function reviewCurrentPathTargets(p){return p.targetRefs?reviewCopyTargets(p):p.nodes.map(id=>S.nodes.find(n=>n.id===id)||{title:'目标已不存在',goal:''})}
function reviewCopyIdentity(p,i=''){return [S.user.id,reviewAccountGeneration,p.id,i].join('|')}
function reviewCopyFind(key){const [owner,generation,id,index]=key.split('|');if(owner!==S.user?.id||Number(generation)!==reviewAccountGeneration||!reviewContextCurrent(reviewContext()))return null;const p=S.paths.find(p=>p.id===id&&Array.isArray(p.targetRefs));return p?{p,index:Number(index)}:null}
function reviewCopyTargets(p){return p.targetRefs.map(r=>{if(r.kind==='public')return r.target;const n=S.nodes.find(n=>n.id===r.nodeId);return n?{nodeId:n.id,title:n.title,goal:n.goal,five:n.five,sourceVersion:n.version,ownership:n.ownership,ownerName:n.ownership==='personal'?S.user.name:undefined,visibility:n.visibility}:{title:'目标已不存在',goal:'请先核对本人目标。',five:'',sourceVersion:0,ownership:'personal'}})}
function reviewCopyConfirmedCount(p){return reviewCopyTargets(p).filter(t=>S.lights.some(l=>{const k=S.events.find(e=>e.id===l.eventId)?.knowledge;return l.confirmed&&l.nodeId===(t.kind==='catalog'?t.originId:t.nodeId)&&k?.nodeGoal===t.goal&&k.nodeVersion===t.sourceVersion})).length}
function reviewCopiedServicePaths(){if(!S.user?.reviewService)return '';return S.paths.filter(p=>Array.isArray(p.targetRefs)&&(U.pathFilter!=='saved'||p.bookmarked)).map(p=>`<article class="path-card"><h2>${esc(p.title)}</h2><p class="small muted">本人私人编排 · 来源 ${esc(p.sourcePathSnapshot.authorName)} / ${esc(p.sourcePathSnapshot.title)} · ${esc(p.sourcePathSnapshot.version.slice(0,8))}</p><p class="small muted">${reviewCopyConfirmedCount(p)} / ${p.targetRefs.length} 个目标有本人确认记录</p><details><summary>查看当前目标顺序与完整定义</summary>${reviewPathBody({title:p.title,targets:reviewCopyTargets(p)})}</details><div class="row">${reviewCopyTargets(p).map((t,i)=>btn('查看目标 · '+t.title,'review-copy-target:'+reviewCopyIdentity(p,i),'ghost')).join('')}${btn('重新编排','review-edit-path-copy:'+reviewCopyIdentity(p),'ghost')}${btn(p.bookmarked?'取消收藏':'收藏本人副本','path-bookmark:'+p.id,'ghost',`aria-pressed="${!!p.bookmarked}"`)}${btn('分享与历史','share-path:'+p.id,'ghost')}</div></article>`).join('')}
async function reviewCopyPublicPath(p,context,button,status){if(!button.isConnected||button.disabled||!reviewContextCurrent(context))return;button.disabled=true;try{const r=await reviewKnowledgeRequest('/api/review-public-paths/one?id='+encodeURIComponent(p.id),{context});if(!button.isConnected||!reviewContextCurrent(context))return;if(r.ownerId!==context.ownerId||JSON.stringify(r.path)!==JSON.stringify(p))throw Error('路径已变化，请重新读取后核对；原内容保留。');const copy={id:uid(),title:p.title,nodes:[],visibility:'private',seed:false,bookmarked:false,sourcePathSnapshot:clone(p),targetRefs:p.targets.map(t=>({kind:'public',target:clone(t)}))};S.paths.push(copy);const saved=save();closeModal();navigate('paths');reviewEditCopiedPath(reviewCopyIdentity(copy));if(!saved)document.getElementById('copied-path-error').textContent='副本留在当前页面，保存未确认，请保留备份。'}catch(e){if(button.isConnected&&reviewContextCurrent(context))status.textContent=reviewIsNetworkError(e)?'来源读取未确认，请重试；原内容保留。':e.message}finally{button.disabled=false}}
function reviewEditCopiedPath(key){const found=reviewCopyFind(key);if(!found)return;const {p}=found,context=reviewContext();let fingerprint=JSON.stringify(p),refs=clone(p.targetRefs);const additions=[...S.nodes.map(n=>({label:n.title+(n.visibility==='private'?' · 本人私人目标':''),ref:{kind:'local',nodeId:n.id}})),...reviewPathBookmarkList().flatMap(b=>b.targets.map(t=>({label:t.title+' · 收藏的公开目标',ref:{kind:'public',target:clone(t)}})))];modal(`<h2>重新编排本人路径</h2><p class="small muted">来源快照保留；调整顺序不会改变节点归属，也不会复制作者进度。</p><form id="copied-path-form"><label>路径名称<input name="title" maxlength="160" value="${esc(p.title)}"></label><div id="copied-path-order"></div><label>添加目标<select id="copied-path-add"><option value="">选择一个目标</option>${additions.map((a,i)=>`<option value="${i}">${esc(a.label)}</option>`).join('')}</select></label><button type="button" id="copied-path-add-button">加入路径</button><button class="primary">保存私人编排</button><p id="copied-path-error" class="error" role="alert"></p></form>`,'','私人路径编排');const f=document.getElementById('copied-path-form'),host=document.getElementById('copied-path-order'),error=document.getElementById('copied-path-error');
 function draw(){host.innerHTML=reviewCopyTargets({targetRefs:refs}).map((t,i)=>`<section class="list-row"><strong>${i+1}. ${esc(t.title)}</strong><p class="small pre">${esc(t.goal)}</p><div class="row"><button type="button" data-copy-up="${i}" ${i?'':'disabled'} aria-label="向前移动目标 ${i+1}">向前</button><button type="button" data-copy-down="${i}" ${i<refs.length-1?'':'disabled'} aria-label="向后移动目标 ${i+1}">向后</button><button type="button" data-copy-remove="${i}" aria-label="移出目标 ${i+1}">移出</button></div></section>`).join('');for(const [attribute,offset] of [['copyUp',-1],['copyDown',1]])host.querySelectorAll('[data-'+attribute.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())+']').forEach(b=>b.addEventListener('click',()=>{if(!f.isConnected||!reviewContextCurrent(context))return;const i=Number(b.dataset[attribute]);[refs[i],refs[i+offset]]=[refs[i+offset],refs[i]];draw()}));host.querySelectorAll('[data-copy-remove]').forEach(b=>b.addEventListener('click',()=>{if(!f.isConnected||!reviewContextCurrent(context))return;refs.splice(Number(b.dataset.copyRemove),1);draw()}))}draw();document.getElementById('copied-path-add-button').addEventListener('click',()=>{if(!f.isConnected||!reviewContextCurrent(context))return;const selected=document.getElementById('copied-path-add').value;if(selected===''||!additions[Number(selected)])return;refs.push(clone(additions[Number(selected)].ref));draw()});f.addEventListener('submit',ev=>{ev.preventDefault();if(!f.isConnected||!reviewContextCurrent(context))return;const title=f.elements.namedItem('title').value.trim(),current=S.paths.find(x=>x.id===p.id);if(!title||!refs.length){error.textContent='请填写名称，并至少保留一个完整目标。';return}if(!current||JSON.stringify(current)!==fingerprint){error.textContent='另一处已修改这个副本，当前填写仍保留，请重新核对。';return}current.title=title;current.targetRefs=clone(refs);fingerprint=JSON.stringify(current);if(!save()){error.textContent='编排留在当前页面，保存未确认，请保留备份。';return}closeModal();navigate('paths');toast('私人编排已保存，来源版本与节点归属保留。')})}
async function reviewOpenCopiedPathTarget(key){const found=reviewCopyFind(key);if(!found)return;const {p,index}=found,r=p.targetRefs[index];if(!r)return;const context=reviewContext(),reference={kind:'private-copy',copyId:p.id,title:p.title,targets:clone(reviewCopyTargets(p)),sourcePath:clone(p.sourcePathSnapshot),targetIndex:index};if(r.kind==='local'){const n=S.nodes.find(n=>n.id===r.nodeId);if(!n){toast('目标不存在，原副本保留。');return}handle('node-nav:'+n.id);U.reviewPathSelection={...context,target:{nodeId:n.id,nodeGoal:n.goal,nodeVersion:n.version},reference};return}
 modal('<h2>核对副本目标</h2><p id="copied-target-loading" role="status">正在核对目标的当前公开版本…</p>','','副本目标');const status=document.getElementById('copied-target-loading'),t=r.target;try{if(t.kind==='personal-public'){const response=await reviewKnowledgeRequest('/api/review-visible-targets/one?nodeId='+encodeURIComponent(t.nodeId),{context});if(!status.isConnected||!reviewContextCurrent(context))return;if(response.ownerId!==context.ownerId||JSON.stringify(reviewComparablePathTarget(response.target,t.kind))!==JSON.stringify(t))throw Error('目标已变化或撤回，原副本快照保留，请重新核对。');reviewShowVisibleTarget(response.target,context,'',reference);return}const response=await reviewKnowledgeRequest('/api/review-public-paths/target?treeId='+encodeURIComponent(t.treeId)+'&nodeId='+encodeURIComponent(t.nodeId),{context});if(!status.isConnected||!reviewContextCurrent(context))return;const current=response.target,n=S.nodes.find(n=>n.id===t.originId);if(response.ownerId!==context.ownerId||JSON.stringify(reviewComparablePathTarget(current||{},t.kind))!==JSON.stringify(t)||!n||n.version!==t.sourceVersion||['title','goal','five','domain','branch','ownership'].some(k=>n[k]!==t[k]))throw Error('目标与副本保存的版本不一致，请先核对。');closeModal();handle('node-nav:'+n.id);U.reviewPathSelection={...context,target:{nodeId:n.id,nodeGoal:n.goal,nodeVersion:n.version},reference};await reviewLoadShared(n.id)}catch(e){if(status.isConnected&&reviewContextCurrent(context))status.textContent=['VISIBLE_TARGET_UNAVAILABLE','PUBLIC_PATH_TARGET_UNAVAILABLE'].includes(e.code)?'目标已撤回，原副本保留；请重新核对可用目标。':reviewIsNetworkError(e)?'目标读取未确认，原副本保留。':e.message}}
